import React, { useEffect, useState } from 'react';
import api from '../services/api';
import { Employee, Project } from '../types';

export function SettingsPage() {
  const [tab, setTab] = useState<'employees' | 'projects'>('employees');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Form states
  const [newEmployee, setNewEmployee] = useState({ name: '', hourly_rate: '', position: '' });
  const [newProject, setNewProject] = useState({ name: '', labor_budget: '', overhead_percentage: '20' });
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    fetchData();
  }, []);

  async function fetchData() {
    try {
      setError(null);
      const [empsData, projsData] = await Promise.all([api.getEmployees(), api.getProjects()]);
      setEmployees(empsData);
      setProjects(projsData);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to load settings');
    } finally {
      setLoading(false);
    }
  }

  async function handleAddEmployee(e: React.FormEvent) {
    e.preventDefault();
    if (!newEmployee.name || !newEmployee.hourly_rate) {
      alert('Name and hourly rate required');
      return;
    }

    try {
      setSaving(true);
      setError(null);
      await api.createEmployee(newEmployee.name, parseFloat(newEmployee.hourly_rate), newEmployee.position);
      setNewEmployee({ name: '', hourly_rate: '', position: '' });
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to create employee');
    } finally {
      setSaving(false);
    }
  }

  async function handleAddProject(e: React.FormEvent) {
    e.preventDefault();
    if (!newProject.name || !newProject.labor_budget) {
      alert('Name and labor budget required');
      return;
    }

    try {
      setSaving(true);
      setError(null);
      await api.createProject(
        newProject.name,
        parseFloat(newProject.labor_budget),
        parseFloat(newProject.overhead_percentage),
      );
      setNewProject({ name: '', labor_budget: '', overhead_percentage: '20' });
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to create project');
    } finally {
      setSaving(false);
    }
  }

  async function deleteEmployee(id: number) {
    if (!confirm('Are you sure?')) return;

    try {
      setError(null);
      await api.deleteEmployee(id);
      fetchData();
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to delete employee');
    }
  }

  if (loading) {
    return (
      <div className="flex justify-center items-center h-screen">
        <p className="text-gray-600">Loading settings...</p>
      </div>
    );
  }

  return (
    <div>
      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      )}

      {/* Tabs */}
      <div className="mb-6 border-b">
        <div className="flex gap-4">
          <button
            onClick={() => setTab('employees')}
            className={`px-4 py-3 font-medium border-b-2 transition-colors ${
              tab === 'employees'
                ? 'border-blue-600 text-blue-600'
                : 'border-transparent text-gray-600 hover:text-gray-900'
            }`}
          >
            Employees
          </button>
          <button
            onClick={() => setTab('projects')}
            className={`px-4 py-3 font-medium border-b-2 transition-colors ${
              tab === 'projects'
                ? 'border-blue-600 text-blue-600'
                : 'border-transparent text-gray-600 hover:text-gray-900'
            }`}
          >
            Projects
          </button>
        </div>
      </div>

      {/* Employees Tab */}
      {tab === 'employees' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Add Employee Form */}
          <div className="lg:col-span-1 bg-white rounded-lg shadow p-6">
            <h3 className="text-lg font-bold text-gray-900 mb-4">Add Employee</h3>
            <form onSubmit={handleAddEmployee} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Name</label>
                <input
                  type="text"
                  value={newEmployee.name}
                  onChange={(e) => setNewEmployee({ ...newEmployee, name: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Hourly Rate</label>
                <input
                  type="number"
                  step="0.01"
                  value={newEmployee.hourly_rate}
                  onChange={(e) => setNewEmployee({ ...newEmployee, hourly_rate: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  placeholder="$25.00"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Position</label>
                <input
                  type="text"
                  value={newEmployee.position}
                  onChange={(e) => setNewEmployee({ ...newEmployee, position: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  placeholder="e.g., Carpenter"
                />
              </div>

              <button
                type="submit"
                disabled={saving}
                className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-medium"
              >
                {saving ? 'Adding...' : 'Add Employee'}
              </button>
            </form>
          </div>

          {/* Employees List */}
          <div className="lg:col-span-2 bg-white rounded-lg shadow overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-6 py-3 text-left font-semibold text-gray-700">Name</th>
                  <th className="px-6 py-3 text-left font-semibold text-gray-700">Position</th>
                  <th className="px-6 py-3 text-left font-semibold text-gray-700">Hourly Rate</th>
                  <th className="px-6 py-3 text-left font-semibold text-gray-700">Action</th>
                </tr>
              </thead>
              <tbody>
                {employees.map((emp) => (
                  <tr key={emp.id} className="border-b hover:bg-gray-50">
                    <td className="px-6 py-3 font-medium text-gray-900">{emp.name}</td>
                    <td className="px-6 py-3 text-gray-600">{emp.position || '-'}</td>
                    <td className="px-6 py-3 font-semibold">${emp.hourly_rate.toFixed(2)}</td>
                    <td className="px-6 py-3">
                      <button
                        onClick={() => deleteEmployee(emp.id)}
                        className="text-red-600 hover:text-red-700 font-medium text-sm"
                      >
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Projects Tab */}
      {tab === 'projects' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Add Project Form */}
          <div className="lg:col-span-1 bg-white rounded-lg shadow p-6">
            <h3 className="text-lg font-bold text-gray-900 mb-4">Add Project</h3>
            <form onSubmit={handleAddProject} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Project Name</label>
                <input
                  type="text"
                  value={newProject.name}
                  onChange={(e) => setNewProject({ ...newProject, name: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Labor Budget</label>
                <input
                  type="number"
                  step="100"
                  value={newProject.labor_budget}
                  onChange={(e) => setNewProject({ ...newProject, labor_budget: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                  placeholder="$50000"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Overhead %
                </label>
                <input
                  type="number"
                  step="0.1"
                  value={newProject.overhead_percentage}
                  onChange={(e) => setNewProject({ ...newProject, overhead_percentage: e.target.value })}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                />
              </div>

              <button
                type="submit"
                disabled={saving}
                className="w-full px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-medium"
              >
                {saving ? 'Adding...' : 'Add Project'}
              </button>
            </form>
          </div>

          {/* Projects List */}
          <div className="lg:col-span-2 bg-white rounded-lg shadow overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="px-6 py-3 text-left font-semibold text-gray-700">Name</th>
                  <th className="px-6 py-3 text-left font-semibold text-gray-700">Labor Budget</th>
                  <th className="px-6 py-3 text-left font-semibold text-gray-700">Overhead %</th>
                  <th className="px-6 py-3 text-left font-semibold text-gray-700">Status</th>
                </tr>
              </thead>
              <tbody>
                {projects.map((proj) => (
                  <tr key={proj.id} className="border-b hover:bg-gray-50">
                    <td className="px-6 py-3 font-medium text-gray-900">{proj.name}</td>
                    <td className="px-6 py-3 font-semibold">${proj.labor_budget.toLocaleString()}</td>
                    <td className="px-6 py-3">{proj.overhead_percentage}%</td>
                    <td className="px-6 py-3 capitalize text-green-600 font-medium">{proj.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}
